SET NOCOUNT ON;
GO
CREATE DATABASE facturacion;
GO
USE facturacion;
GO
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE TABLE dbo.clientes (
    id       INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
    nif      VARCHAR(15)   NOT NULL,
    nombre   NVARCHAR(150) NOT NULL,
    email    VARCHAR(150)  NULL,
    telefono VARCHAR(20)   NULL
);

CREATE TABLE dbo.tarifas (
    id          INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
    codigo      VARCHAR(20)   NOT NULL UNIQUE,
    descripcion NVARCHAR(100) NOT NULL
);

CREATE TABLE dbo.tarifas_precios (
    id               INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
    tarifa_id        INT           NOT NULL REFERENCES dbo.tarifas (id),
    precio_kwh       DECIMAL(10,6) NOT NULL,
    termino_fijo_mes DECIMAL(10,2) NOT NULL,
    vigente_desde    DATE          NOT NULL,
    vigente_hasta    DATE          NULL
);

CREATE TABLE dbo.contratos (
    id            INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
    cliente_id    INT         NOT NULL REFERENCES dbo.clientes (id),
    cups          VARCHAR(22) NOT NULL,
    tarifa_id     INT         NOT NULL REFERENCES dbo.tarifas (id),
    distribuidora VARCHAR(20) NOT NULL,
    forma_pago    VARCHAR(15) NOT NULL CHECK (forma_pago IN ('domiciliacion', 'transferencia')),
    estado        VARCHAR(10) NOT NULL CHECK (estado IN ('activo', 'baja')),
    fecha_alta    DATE        NOT NULL,
    fecha_baja    DATE        NULL
);

CREATE TABLE dbo.lecturas (
    id               INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
    contrato_id      INT           NOT NULL REFERENCES dbo.contratos (id),
    fecha_desde      DATE          NOT NULL,
    fecha_hasta      DATE          NOT NULL,
    lectura_contador INT           NOT NULL, -- valor del contador en fecha_hasta
    consumo_kwh      DECIMAL(12,3) NOT NULL, -- consumo del periodo
    tipo             VARCHAR(10)   NOT NULL CHECK (tipo IN ('real', 'estimada')),
    fichero_origen   VARCHAR(60)   NOT NULL,
    fecha_carga      DATETIME2(0)  NOT NULL
);

CREATE TABLE dbo.log_procesos (
    id               INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
    proceso          VARCHAR(40)    NOT NULL,
    parametros       VARCHAR(100)   NULL,
    inicio           DATETIME2(0)   NOT NULL,
    fin              DATETIME2(0)   NULL,
    estado           VARCHAR(10)    NOT NULL CHECK (estado IN ('EN_CURSO', 'OK', 'ERROR')),
    filas_procesadas INT            NULL,
    usuario          VARCHAR(50)    NOT NULL,
    mensaje          NVARCHAR(400)  NULL
);

CREATE TABLE dbo.facturas (
    id              INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
    numero          VARCHAR(20)   NOT NULL UNIQUE,
    contrato_id     INT           NOT NULL REFERENCES dbo.contratos (id),
    periodo         CHAR(7)       NOT NULL, -- 'YYYY-MM'
    fecha_desde     DATE          NOT NULL,
    fecha_hasta     DATE          NOT NULL,
    consumo_kwh     DECIMAL(12,3) NOT NULL,
    precio_kwh      DECIMAL(10,6) NOT NULL,
    importe_energia DECIMAL(12,2) NOT NULL,
    importe_fijo    DECIMAL(10,2) NOT NULL,
    total           DECIMAL(12,2) NOT NULL,
    estado          VARCHAR(10)   NOT NULL CHECK (estado IN ('borrador', 'emitida', 'pagada', 'anulada')),
    ejecucion_id    INT           NULL REFERENCES dbo.log_procesos (id),
    fecha_creacion  DATETIME2(0)  NOT NULL,
    fecha_emision   DATE          NULL,
    fecha_pago      DATE          NULL
);

CREATE TABLE dbo.reclamaciones (
    id         INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
    fecha      DATETIME2(0)   NOT NULL,
    cliente_id INT            NOT NULL REFERENCES dbo.clientes (id),
    canal      VARCHAR(10)    NOT NULL,
    texto      NVARCHAR(1000) NOT NULL
);

CREATE INDEX ix_contratos_cliente ON dbo.contratos (cliente_id);
CREATE INDEX ix_lecturas_contrato ON dbo.lecturas (contrato_id, fecha_hasta);
CREATE INDEX ix_facturas_contrato_periodo ON dbo.facturas (contrato_id, periodo);
GO

-- INSERTS en la tabla 'clientes'
SET IDENTITY_INSERT dbo.clientes ON;
SET IDENTITY_INSERT dbo.clientes OFF;
GO
-- INSERTS en la tabla 'tarifas'
SET IDENTITY_INSERT dbo.tarifas ON;
SET IDENTITY_INSERT dbo.tarifas OFF;
GO
-- INSERTS en la tabla 'tarifas_precios'
SET IDENTITY_INSERT dbo.tarifas_precios ON;
SET IDENTITY_INSERT dbo.tarifas_precios OFF;
GO
-- INSERTS en la tabla 'contratos'
SET IDENTITY_INSERT dbo.contratos ON;
SET IDENTITY_INSERT dbo.contratos OFF;
GO
-- INSERTS en la tabla 'lecturas'
SET IDENTITY_INSERT dbo.lecturas ON;
SET IDENTITY_INSERT dbo.lecturas OFF;
GO
-- INSERTS en la tabla 'log_procesos'
SET IDENTITY_INSERT dbo.log_procesos ON;
SET IDENTITY_INSERT dbo.log_procesos OFF;
GO
-- INSERTS en la tabla 'facturas'
SET IDENTITY_INSERT dbo.facturas ON;
SET IDENTITY_INSERT dbo.facturas OFF;
GO
-- INSERTS en la tabla 'reclamaciones'
SET IDENTITY_INSERT dbo.reclamaciones ON;
SET IDENTITY_INSERT dbo.reclamaciones OFF;
GO
CREATE SEQUENCE dbo.seq_factura AS INT START WITH 907 INCREMENT BY 1;
GO

CREATE OR ALTER PROCEDURE dbo.sp_facturar_periodo
    @periodo CHAR(7) -- 'YYYY-MM'
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @inicio DATE = CONVERT(DATE, @periodo + '-01', 23);
    DECLARE @fin    DATE = EOMONTH(@inicio);
    DECLARE @ejecucion_id INT;
    DECLARE @procesados   INT = 0;
    DECLARE @contrato_id  INT;
    DECLARE @tarifa_id    INT;
    DECLARE @consumo      DECIMAL(12,3);
    DECLARE @precio       DECIMAL(10,6);
    DECLARE @fijo         DECIMAL(10,2);
    DECLARE @importe      DECIMAL(12,2);
    DECLARE @numero       INT;

    VALUES ('FACTURACION_MENSUAL', @periodo, SYSDATETIME(), 'EN_CURSO', SUSER_SNAME());
    SET @ejecucion_id = SCOPE_IDENTITY();

    DECLARE contratos_cur CURSOR LOCAL FAST_FORWARD FOR
        SELECT id, tarifa_id
        FROM dbo.contratos
        WHERE fecha_alta <= @fin
          AND (fecha_baja IS NULL OR fecha_baja >= @inicio)
        ORDER BY id;

    OPEN contratos_cur;
    FETCH NEXT FROM contratos_cur INTO @contrato_id, @tarifa_id;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        -- Consumo del periodo
        SELECT @consumo = ISNULL(SUM(consumo_kwh), 0)
        FROM dbo.lecturas
        WHERE contrato_id = @contrato_id
          AND fecha_hasta BETWEEN @inicio AND @fin;

        -- Precio vigente de la tarifa
        SELECT @precio = precio_kwh,
               @fijo   = termino_fijo_mes
        FROM dbo.tarifas_precios
        WHERE tarifa_id = @tarifa_id
          AND vigente_hasta IS NULL;

        SET @importe = ROUND(@consumo * @precio, 2);
        SET @numero = NEXT VALUE FOR dbo.seq_factura;

                                  precio_kwh, importe_energia, importe_fijo, total, estado,
                                  ejecucion_id, fecha_creacion)
        VALUES (CONCAT('F', LEFT(@periodo, 4), '-', FORMAT(@numero, '000000')),
                @contrato_id, @periodo, @inicio, @fin, @consumo,
                @precio, @importe, @fijo, @importe + @fijo, 'borrador',
                @ejecucion_id, SYSDATETIME());

        SET @procesados += 1;
        FETCH NEXT FROM contratos_cur INTO @contrato_id, @tarifa_id;
    END

    CLOSE contratos_cur;
    DEALLOCATE contratos_cur;

    UPDATE dbo.log_procesos
    SET fin = SYSDATETIME(),
        estado = 'OK',
        filas_procesadas = @procesados
    WHERE id = @ejecucion_id;
END
GO

