INSERT INTO dbo.reclamaciones (id, fecha, cliente_id, canal, texto) VALUES
(1, '2026-10-08T10:24:00', 23, N'email', N'Me han llegado dos facturas de septiembre con números distintos (F2026-000725 y F2026-000786) y el mismo importe. ¿Cuál tengo que pagar?'),
(2, '2026-10-09T17:02:00', 88, N'web', N'La factura de septiembre es el doble de lo habitual y medio mes estuve de vacaciones. Revisadlo, por favor.'),
(3, '2026-10-10T12:41:00', 119, N'email', N'En la factura de septiembre aparecen 632 kWh, muchísimo más que en agosto (313 kWh). El contador no puede marcar eso.'),
(4, '2026-10-13T09:15:00', 104, N'email', N'Me avisasteis de que el precio de mi tarifa subía a partir del 15 de septiembre, pero en la factura de septiembre todo el consumo va al precio nuevo.'),
(5, '2026-10-14T11:52:00', 7, N'telefono', N'El banco me ha cargado dos recibos de la factura de septiembre de 35,88 € cada uno. Quiero que me devolváis uno ya.'),
(6, '2026-10-15T16:30:00', 41, N'telefono', N'Me habéis pasado dos recibos de septiembre y además los dos son mucho más altos de lo normal. No entiendo nada.'),
(7, '2026-10-16T10:05:00', 97, N'telefono', N'Los últimos meses pagaba unos 23,15 € y la factura de septiembre es de 110,29 €. Es un abuso y quiero que la revisen.');
